query.base:
FROM metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/storage/total_bytes` IS NOT NULL
//
// --- Snapshot handling -------------------------------------------------------------------------
// total_bytes is a point-in-time snapshot recomputed by Cloud Monitoring roughly once per day and
// re-reported on every poll. It must NEVER be summed over time: that would multiply it by the poll
// count. Only the 2-day head and tail slices of the window are compared; both always contain a
// daily snapshot.
| EVAL slice = CASE(@timestamp >= NOW() - 2 days, "latest", @timestamp < NOW() - 12 days, "earliest", null)
| WHERE slice IS NOT NULL
// A bucket can hold several storage classes at once (lifecycle transitions, Autoclass). Classes are
// summed within each hour so that every bucket total comes from one coherent set of polls. Summing
// per-class maxima taken across a whole slice would count data twice if it changed class inside it.
| STATS class_bytes = MAX(`metrics.storage.googleapis.com/storage/total_bytes`)
    BY resource.attributes.bucket_name, attributes.storage_class, slice, hour = BUCKET(@timestamp, 1 hour)
// Everything that is not an archival class is billed at a hot rate. Written as an exclusion so that
// an unfamiliar class is counted as hot rather than silently ignored.
| EVAL hot_class_bytes = CASE(attributes.storage_class NOT IN ("NEARLINE", "COLDLINE", "ARCHIVE"), class_bytes, 0.0)
| STATS bucket_bytes = SUM(class_bytes),
        bucket_hot_bytes = SUM(hot_class_bytes),
        hour_classes = VALUES(attributes.storage_class)
    BY resource.attributes.bucket_name, slice, hour
// The median hourly total ignores the odd hour that straddles a class change or misses a poll.
| STATS latest_bytes     = MEDIAN(bucket_bytes) WHERE slice == "latest",
        earliest_bytes   = MEDIAN(bucket_bytes) WHERE slice == "earliest",
        latest_hot_bytes = MEDIAN(bucket_hot_bytes) WHERE slice == "latest",
        storage_classes  = VALUES(hour_classes)
    BY resource.attributes.bucket_name

breach.segment:
// Guard against divide-by-zero, and ignore buckets too small for growth to cost anything.
// 10 GiB; raise this so only buckets that matter to the bill can alert.
WHERE earliest_bytes > 0 AND latest_bytes >= 10737418240
| EVAL growth_gib = ROUND((latest_bytes - earliest_bytes) / 1073741824.0, 2),
       growth_pct = ROUND((latest_bytes - earliest_bytes) / earliest_bytes * 100.0, 2),
       latest_gib = ROUND(latest_bytes / 1073741824.0, 2),
       hot_bytes_pct = ROUND(COALESCE(latest_hot_bytes, 0.0) / latest_bytes * 100.0, 1)
// 50% over 14 days is roughly a doubling per month. Lower to 25 for tighter budget control, or
// raise it for buckets that are expected to grow quickly.
| WHERE growth_pct > 50.0
| SORT growth_pct DESC
| LIMIT 50
